use serde::{Deserialize, Serialize};
use std::path::Path;

use crate::config::AgentConfig;
use crate::model::{ChatMessage, CompletionRequest, Model};
use crate::sandbox::Sandbox;
use crate::store::Store;

/// Individual diagnostic check result.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct CheckResult {
    pub name: String,
    pub passed: bool,
    pub message: String,
    pub remediation: Option<String>,
}

/// Comprehensive diagnostics report generated by `s3a-harness doctor`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DoctorReport {
    pub all_healthy: bool,
    pub checks: Vec<CheckResult>,
}

impl DoctorReport {
    pub fn new(checks: Vec<CheckResult>) -> Self {
        let all_healthy = checks.iter().all(|c| c.passed);
        Self {
            all_healthy,
            checks,
        }
    }
}

/// Runs full operability diagnostics verifying configuration, model, store, and sandbox.
pub fn run_doctor(
    config_path: Option<&Path>,
    model: &dyn Model,
    store: &dyn Store,
    sandbox: &Sandbox,
) -> DoctorReport {
    let mut checks = Vec::new();

    // 1. Config Validation Check
    let config_check = if let Some(path) = config_path {
        match AgentConfig::load_file(path) {
            Ok(cfg) => CheckResult {
                name: "Configuration Validation".to_string(),
                passed: true,
                message: format!(
                    "Config file '{}' for agent '{}' is valid with all threshold constraints satisfied",
                    path.display(),
                    cfg.id
                ),
                remediation: None,
            },
            Err(e) => CheckResult {
                name: "Configuration Validation".to_string(),
                passed: false,
                message: format!("Config file '{}' failed validation: {}", path.display(), e),
                remediation: Some(
                    "Check required fields (agent.id, agent.model, positive limits, thresholds within [0.0, 1.0])"
                        .to_string(),
                ),
            },
        }
    } else {
        CheckResult {
            name: "Configuration Validation".to_string(),
            passed: true,
            message: "No specific config file specified; built-in defaults valid".to_string(),
            remediation: None,
        }
    };
    checks.push(config_check);

    // 2. Model Reachability Check
    let model_req = CompletionRequest::new(vec![ChatMessage::user("ping")]);
    let model_check = match model.complete(&model_req) {
        Ok(resp) => CheckResult {
            name: "Model Reachability".to_string(),
            passed: true,
            message: format!("Model '{}' reachable (response received)", resp.model),
            remediation: None,
        },
        Err(e) => CheckResult {
            name: "Model Reachability".to_string(),
            passed: false,
            message: format!("Model '{}' unreachable: {}", model.model_id(), e),
            remediation: Some(
                "Verify model backend is running (e.g. `ollama serve`) or run with `--mock`"
                    .to_string(),
            ),
        },
    };
    checks.push(model_check);

    // 3. Store Reachability Check
    let store_check = match store.list_academic_verbs() {
        Ok(verbs) => CheckResult {
            name: "Store Reachability".to_string(),
            passed: true,
            message: format!(
                "Store is reachable and accessible for queries ({} verbs available)",
                verbs.len()
            ),
            remediation: None,
        },
        Err(e) => CheckResult {
            name: "Store Reachability".to_string(),
            passed: false,
            message: format!("Store query failed: {}", e),
            remediation: Some(
                "Ensure local S3A file is accessible or remote LRS endpoint is online and authorized"
                    .to_string(),
            ),
        },
    };
    checks.push(store_check);

    // 4. Sandbox Integrity Check
    let sandbox_check = {
        let root = sandbox.root();
        if root.exists() {
            let exports = sandbox.exports_dir();
            if exports.exists() || std::fs::create_dir_all(&exports).is_ok() {
                CheckResult {
                    name: "Sandbox Integrity".to_string(),
                    passed: true,
                    message: format!(
                        "Sandbox root '{}' and exports directory verified",
                        root.display()
                    ),
                    remediation: None,
                }
            } else {
                CheckResult {
                    name: "Sandbox Integrity".to_string(),
                    passed: false,
                    message: format!("Cannot create exports directory in '{}'", root.display()),
                    remediation: Some(
                        "Check filesystem write permissions for sandbox directory".to_string(),
                    ),
                }
            }
        } else {
            CheckResult {
                name: "Sandbox Integrity".to_string(),
                passed: false,
                message: format!("Sandbox root '{}' does not exist", root.display()),
                remediation: Some("Specify an existing directory with `--root <path>`".to_string()),
            }
        }
    };
    checks.push(sandbox_check);

    DoctorReport::new(checks)
}
